"""An original illustrated laboratory header with real research connections."""
from bs4 import BeautifulSoup

def header(root):
    labs=root/'labs'
    svg='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 440"><defs><pattern id="tiles" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#365269" stroke-width="1"/></pattern><pattern id="holes" width="22" height="18" patternUnits="userSpaceOnUse"><rect x="6" y="5" width="10" height="6" fill="#23414e"/></pattern></defs><rect width="1200" height="440" fill="#132d3b"/><rect width="1200" height="440" fill="url(#tiles)"/><path d="M0 35H140V70H1080V35H1200M20 390H1180" fill="none" stroke="#08141e" stroke-width="18"/><path d="M0 35H140V70H1080V35H1200M20 390H1180" fill="none" stroke="#6d8d9c" stroke-width="8"/><g fill="#e2f2e3" stroke="#08141e" stroke-width="5"><path d="M170 60h180l-25 30H195Z"/><path d="M490 60h180l-25 30H515Z"/><path d="M850 60h180l-25 30H875Z"/></g><g font-family="Arial,sans-serif" font-weight="800" fill="#e8f0df"><text x="45" y="125" font-size="16">THE BOOK ARCHIVE</text><text x="405" y="125" font-size="16">BABBAGE / COMPUTATION</text><text x="795" y="125" font-size="16">NECHVATAL / ART + ARTIFICIAL LIFE</text></g>
<g stroke="#08141e" stroke-width="6" stroke-linejoin="round"><rect x="45" y="145" width="280" height="205" rx="5" fill="#765582"/><path d="M58 238H313M58 333H313" stroke="#f4d970" stroke-width="10"/><rect x="65" y="161" width="35" height="66" fill="#c6ef77"/><rect x="106" y="156" width="47" height="71" fill="#f2c85a"/><rect x="159" y="170" width="32" height="57" fill="#7fb9dc"/><path d="m204 163 35-6 13 70h-35Z" fill="#f08fab"/><rect x="257" y="162" width="42" height="65" fill="#c5badf"/><rect x="65" y="251" width="232" height="27" fill="#c6ef77"/><rect x="73" y="281" width="220" height="23" fill="#f5d571"/><rect x="63" y="307" width="240" height="19" fill="#95bde0"/>
<rect x="400" y="165" width="310" height="168" rx="8" fill="#76939c"/><rect x="418" y="180" width="274" height="120" fill="#223845"/><path d="M440 192v95M470 192v95M500 192v95M530 192v95M560 192v95M590 192v95M620 192v95M650 192v95" stroke="#c8b48a" stroke-width="9"/>
<rect x="788" y="145" width="360" height="205" rx="8" fill="#788c9f"/><rect x="805" y="161" width="326" height="160" fill="#362657"/><path d="M817 276q50-130 100-20t100-34 95 45" stroke="#b275bf" stroke-width="24" fill="none"/><path d="M818 205q60 90 140-5t155 66" stroke="#f08faa" stroke-width="11" fill="none"/><path d="m834 295 60-90 40 70 95-88 65 106" stroke="#b6e874" stroke-width="4" fill="none"/>
<path d="M30 355H1170v25H30ZM70 380v47M1125 380v47" fill="#a4bbc1"/><path d="M326 319h45v-80h29M710 243h78" fill="none" stroke="#08141e" stroke-width="13"/><path d="M326 319h45v-80h29M710 243h78" fill="none" stroke="#c7ec7e" stroke-width="5"/>
<path d="M480 310h155v88H480Z" fill="#ecddb0"/><rect x="495" y="322" width="125" height="59" fill="url(#holes)" stroke="none"/>
<rect x="750" y="311" width="225" height="103" rx="7" fill="#a6bac7"/><rect x="765" y="325" width="195" height="67" fill="#112a30"/><path d="M790 349h70m-70 17h140m-140 12h90" stroke="#c9ed84" stroke-width="5"/><circle cx="1110" cy="374" r="16" fill="#ffd34a"/><circle cx="1060" cy="374" r="16" fill="#b4e37a"/>
</g>'''
    for x in [453,520,587,654]:
        svg+=f'<g stroke="#08141e" stroke-width="5"><circle cx="{x}" cy="236" r="31" fill="#e2bb57"/><circle cx="{x}" cy="236" r="11" fill="#8e6974"/><path d="M{x-35} 236h70m-35-35v70" stroke="#08141e" stroke-width="7"/></g>'
    svg+='''<g font-family="monospace" font-weight="700" fill="#142c37"><text x="77" y="270" font-size="14">GAMEWORLD INTERFACES</text><text x="83" y="298" font-size="13">DESIGN JUSTICE</text><text x="76" y="322" font-size="12">DATA / MEDIA / LITERATURE</text></g><g font-family="monospace" font-weight="700" fill="#e4ecdf" font-size="13"><text x="440" y="428">RULES → POSSIBILITIES</text><text x="782" y="434">AI / WHO DECIDES?</text></g></svg>'''
    (labs/'digital-culture-laboratory.svg').write_text(svg,encoding='utf-8',newline='\n')
    path=labs/'academic-library.html';s=BeautifulSoup(path.read_text(encoding='utf-8'),'html.parser')
    hero=s.select_one('.al-hero');hero.clear()
    hero.append(BeautifulSoup('''<p class="al-tag">THE LAB / DIGITAL CULTURE</p><h1>Welcome to the laboratory.</h1><p class="al-intro">Books, machines, art and ideas. Find the research behind what you want to make.</p><figure class="lc-scene"><img src="digital-culture-laboratory.svg" width="1200" height="440" alt="An illustrated digital culture laboratory: academic books feed a Babbage-inspired calculating engine, beside an artificial-life art chamber and an AI terminal."/></figure><nav class="lc-benches" aria-label="Choose a research workbench"><a href="#research-finder"><strong>Find my research</strong><span>Bring your project. We help you find the words.</span></a><a href="#sources"><strong>The book archive</strong><span>Games, literature, design, data and power.</span></a><a href="#genre-explorer"><strong>Explore the collection</strong><span>Discover forms, genres and possibilities.</span></a><a href="#aesthetics"><strong>The aesthetics bench</strong><span>Experiment with how your work looks and feels.</span></a></nav><details class="lc-history"><summary>Meet the ideas behind the laboratory</summary><p><strong>Charles Babbage:</strong> his designs for calculating engines connect this room to the history of programmable machines. <a href="https://collection.sciencemuseumgroup.org.uk/objects/co62245/babbages-analytical-engine-1834-1871-trial-model" target="_blank" rel="noopener">See the Science Museum's Analytical Engine trial model</a>.</p><p><strong>Joseph Nechvatal:</strong> his computer-assisted paintings and artificial-life work connect code, art and aesthetics. <a href="https://josephnechvatal.wordpress.com/about/" target="_blank" rel="noopener">Read the artist's introduction</a>.</p><p><strong>AI:</strong> a tool and a research question. Who contributes, whose material is involved, and how do you evaluate what it produces?</p><p>The laboratory is an original illustration, not a reconstruction of a historical room or a reproduction of Nechvatal's artwork.</p></details>''','html.parser'))
    # Remove generic transition captions; retain useful links and the keyboard shortcut.
    for a in s.select('a[href]'):
        if a.get_text(' ',strip=True)=='Next: find an academic source →':a.string='Browse the academic books →'
    link=s.select_one('link[href^="academic-library-theme.css"]');link['href']='academic-library-theme.css?v=learning-10'
    path.write_text(str(s),encoding='utf-8',newline='\n')
